import ProjectListItem from "./projectsItem";

// A row in the left-hand table of contents. Both projects and blog posts
// are mapped to this shape so they share one list. The subtitle isn't shown
// in the list right now but is kept for later use.
export interface ListEntry {
  key: string;
  title: string;
  subtitle: string;
  year: string;
  category: string;
}

interface ContentListProps {
  categories: readonly string[];
  entries: readonly ListEntry[];
  selectedKey?: string;
  onSelect: (key: string) => void;
  // Other people reading each entry's page
  readers?: (key: string) => number;
  emptyText?: string;
}

const ContentList = ({
  categories,
  entries,
  selectedKey,
  onSelect,
  readers,
  emptyText,
}: ContentListProps) => (
  // The extra left padding (offset by the negative margin) leaves room for
  // the reader counts beside each title
  <nav
    data-cursor-panel="list"
    className="-ml-5 min-h-0 flex-1 overflow-y-auto pb-16 pl-10 pr-8">
    {entries.length === 0 && emptyText && (
      <p className="select-none py-1 font-mono text-neutral-600">
        {emptyText}
      </p>
    )}
    {categories.map((category) =>
    {
      const inCategory = entries.filter((e) => e.category === category);
      if (inCategory.length === 0)
      {
        return null;
      }
      return (
        <div key={category} className="flex flex-col">
          <p className="select-none py-1 font-mono text-white opacity-15">
            {category}
          </p>
          {inCategory.map((entry) => (
            <ProjectListItem
              key={entry.key}
              title={entry.title}
              year={entry.year}
              selected={entry.key === selectedKey}
              readers={readers?.(entry.key) ?? 0}
              onClick={() => onSelect(entry.key)}
            />
          ))}
        </div>
      );
    })}
  </nav>
);

export default ContentList;
